import{_ as l,o,c as a,a2 as i}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"插件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guides/plugins.md","filePath":"zh/guides/plugins.md","lastUpdated":1781675678000}'),t={name:"zh/guides/plugins.md"};function r(d,e,n,s,u,c){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h1><p>插件是从 Supermarket 安装到某个 Bot 的能力包。在 v0.13 中，插件 manifest 可以描述受管理的 MCP 资源、打包的 Skills、插件 Hooks、配置变量、认证要求，以及可选的安装命令。</p><p>Memoh 会把当前配置的 Supermarket endpoint 视为可信插件来源。默认 endpoint 是 <code>https://supermarket.memoh.ai</code>，部署方也可以通过服务端 <code>supermarket.base_url</code> 配置覆盖。</p><hr><h2 id="插件能提供什么" tabindex="-1">插件能提供什么 <a class="header-anchor" href="#插件能提供什么" aria-label="Permalink to &quot;插件能提供什么&quot;">​</a></h2><p>插件 manifest 可以包含：</p><ul><li><strong>MCP 资源</strong>：Memoh 会创建为插件托管的 MCP 连接，用来接入外部工具或服务。</li><li><strong>Skills</strong>：可复用的 Markdown 行为模块，可以在 manifest 中引用，也可以随插件 bundle 一起打包。</li><li><strong>Hooks</strong>：插件 bundle 可提供 <code>hooks.json</code>，用于在支持的 Hook 事件中执行插件动作。</li><li><strong>配置变量</strong>：安装时收集必填或可选值，也支持 secret 值。</li><li><strong>认证要求</strong>：支持 <code>managed_oauth</code>、<code>user_secret</code>，或不需要认证的 MCP 设置。</li><li><strong>安装命令</strong>：<code>install</code> 字段可以是一个字符串，也可以是字符串数组。</li></ul><p>插件托管的 MCP 资源通常是插件的实现细节。用户管理的是插件这个产品边界，而不是手动管理每一个由插件生成的 MCP 连接。</p><hr><h2 id="可信插件-bundle" tabindex="-1">可信插件 Bundle <a class="header-anchor" href="#可信插件-bundle" aria-label="Permalink to &quot;可信插件 Bundle&quot;">​</a></h2><p>从 Supermarket 安装插件时，Memoh 会：</p><ol><li>从 Supermarket 获取插件 manifest。</li><li>在存在插件 bundle 时从 Supermarket 下载 bundle。</li><li>只把可信 bundle 中的下列路径解压到 Bot 工作区的插件区域： <ul><li><code>skills/</code></li><li><code>hooks.json</code></li><li><code>scripts/</code></li></ul></li><li>在插件目录中执行 manifest 的 <code>install</code> 命令。</li><li>创建插件安装记录和插件托管的 MCP 资源。</li></ol><p>解压后的插件根目录位于 Bot 工作区内的 <code>/data/.memoh/plugins/&lt;plugin_id&gt;</code>。同一个插件 id 重新安装时，Memoh 会先清空该插件根目录，再解压新的 bundle。</p><p>安装命令会在插件根目录中运行，并带上这些环境变量：</p><ul><li><code>MEMOH_PLUGIN_ID</code></li><li><code>MEMOH_PLUGIN_DIR</code></li><li><code>MEMOH_BOT_ID</code></li></ul><p>只安装可信 Supermarket 插件，因为 bundle 文件和安装命令会在目标 Bot 工作区中执行。</p><hr><h2 id="bot-插件管理" tabindex="-1">Bot 插件管理 <a class="header-anchor" href="#bot-插件管理" aria-label="Permalink to &quot;Bot 插件管理&quot;">​</a></h2><p>打开 Bot 的 <strong>详情页</strong>，进入 <strong>Plugins</strong> tab，可以查看该 Bot 已安装的插件。</p><p>在 v0.13 中，Plugins tab 会显示：</p><ul><li>已安装插件的名称、描述、图标和主页链接</li><li>插件状态</li><li>当前安装是否启用</li><li>需要 managed OAuth 时显示 <strong>Authorize</strong> 操作</li><li>对 <code>ready</code> 或 <code>disabled</code> 插件显示启停开关</li><li>返回 Supermarket 安装更多插件的入口</li></ul><p>插件 API 也支持 Bot 级别的列表、详情、启用、禁用、卸载、清理、managed OAuth 授权，以及 OAuth 状态刷新操作。</p><hr><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>插件安装记录使用这些状态值：</p><ul><li><code>ready</code>：插件已有所需配置和认证；Memoh 可以启用它托管的资源。</li><li><code>needs_config</code>：缺少必填的 manifest 变量、环境变量、header，或 user-secret 值。</li><li><code>needs_auth</code>：插件需要 managed OAuth，但该 Bot 还没有完成授权。</li><li><code>admin_required</code>：插件声明了 managed OAuth <code>client_ref</code>，但 Memoh 服务端还没有为该引用配置可用的 OAuth client。</li><li><code>disabled</code>：插件已被关闭；插件托管的 MCP 连接处于 inactive。</li><li><code>uninstalled</code>：插件已从 Bot 卸载；托管 MCP 连接和插件资源记录已移除。</li></ul><p>清理安装记录会删除安装记录和已保存配置。安装未启用时，已解压的 bundle 文件不会被发现；之后重新安装会重写插件根目录。</p><hr><h2 id="认证" tabindex="-1">认证 <a class="header-anchor" href="#认证" aria-label="Permalink to &quot;认证&quot;">​</a></h2><p>插件主要有两种认证模型：</p><ul><li><strong>Managed OAuth</strong>：manifest 声明 <code>auth_requirements[].type = &quot;managed_oauth&quot;</code>。如果它使用 <code>client_ref</code>，运维方需要在 Memoh 服务端配置对应 OAuth client。用户随后可以在 Supermarket 安装流程或 Bot 的 Plugins tab 中为插件授权。</li><li><strong>User secret</strong>：manifest 声明必填变量、环境变量或 headers。用户安装时填写这些值。缺少必填值时，插件会进入 <code>needs_config</code>。</li></ul><p>Managed OAuth 成功后，Memoh 会刷新插件状态，并在插件进入 <code>ready</code> 后启用托管 MCP 资源。</p><hr><h2 id="插件和其它功能的关系" tabindex="-1">插件和其它功能的关系 <a class="header-anchor" href="#插件和其它功能的关系" aria-label="Permalink to &quot;插件和其它功能的关系&quot;">​</a></h2><ul><li><strong>Supermarket</strong> 用来发现和安装插件以及独立 Skills。</li><li><strong>Skills</strong> 可以来自独立的 Supermarket Skill，也可以来自已启用的插件 bundle。</li><li><strong>MCP</strong> 资源可以由插件创建和管理；插件托管的 MCP 资源可能不会出现在普通 MCP 管理入口中。</li><li><strong>Hooks</strong> 可以由已启用且状态为 <code>ready</code> 的插件 bundle 通过 <code>hooks.json</code> 提供。</li></ul><hr><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="/zh/guides/supermarket.html">Supermarket</a></li><li><a href="/zh/guides/skills.html">技能</a></li><li><a href="/zh/guides/mcp.html">MCP</a></li><li><a href="/zh/guides/bot.html">机器人</a></li></ul>',38)])])}const m=l(t,[["render",r]]);export{p as __pageData,m as default};
